def _icon(name):
    return '<svg class="cc-icon" viewBox="0 0 24 24" aria-hidden="true">'+_ICONS[name]+'</svg>'

def apply_member_shell(html,user,current):
    main_current=' aria-current="page"' if current=='main' else ''
    mypage_current=' aria-current="page"' if current=='mypage' else ''
    header='''<header class="cc-header"><div class="cc-header-inner"><div class="cc-header-left">
<button class="cc-icon-button" id="cc-menu-toggle" type="button" aria-label="메뉴 열기" aria-controls="cc-menu" aria-expanded="false">'''+_icon('menu')+'''</button>
<a class="cc-brand" href="/main" aria-label="취준나침반 메인"><svg class="cc-brand-mark" viewBox="0 0 44 44" aria-hidden="true"><circle cx="22" cy="22" r="21" fill="#f7ca43"/><path d="m31 10-5 16-13 8 5-16Z" fill="#263127"/><path d="m31 10-9 12-4-4Z" fill="#fffaf0"/></svg><span>취준나침반</span></a></div>
<nav class="cc-header-right" aria-label="상단 메뉴"><a class="cc-top-button cc-main-button" href="/main"'''+main_current+'''>메인</a><a class="cc-top-button cc-mypage-button" href="/mypage"'''+mypage_current+'''>마이페이지</a><span class="cc-member-name username">__CC_USER_NAME__님</span><button class="cc-top-button cc-logout-button" type="button" id="cc-logout">로그아웃</button></nav></div></header>
<p class="cc-shell-message" id="cc-shell-message" role="status" aria-live="polite" hidden></p>'''
    menu='''<div class="cc-menu-backdrop" id="cc-menu-backdrop" hidden></div><aside class="cc-menu" id="cc-menu" inert aria-label="주 메뉴"><div class="cc-menu-heading"><span>나의 취준나침반</span><button class="cc-icon-button" id="cc-menu-close" type="button" aria-label="메뉴 닫기">'''+_icon('close')+'''</button></div><p class="cc-menu-label">YOUR NEXT DIRECTION</p><nav class="cc-menu-list" aria-label="서비스 메뉴">
<a class="cc-menu-item" href="/main"'''+main_current+'>'+_icon('home')+'''메인</a>
<a class="cc-menu-item" href="/jd_match">'''+_icon('target')+'''적합도 분석</a>
<a class="cc-menu-item" href="/training_match">'''+_icon('book')+'''교육추천</a>
<button class="cc-menu-item" type="button" data-cc-pending="jobs">'''+_icon('case')+'''공고모음<span class="cc-soon">준비 중</span></button>
<a class="cc-menu-item" href="/training_posts">'''+_icon('grid')+'''교육모음</a>
<a class="cc-menu-item cc-menu-last" href="/mypage"'''+mypage_current+'>'+_icon('user')+'''마이페이지</a></nav><p class="cc-menu-note">각자의 속도로,<br>더 선명한 내일을 향해.</p></aside>
<dialog class="cc-service-dialog" id="cc-service-dialog" aria-labelledby="cc-service-title"><h2 id="cc-service-title"></h2><p id="cc-service-body"></p><form method="dialog"><button class="cc-dialog-confirm" value="close">확인</button></form></dialog>'''
    for key,value in [('__CC_CSS__',CSS),('__CC_HEADER__',header),('__CC_MENU__',menu),('__CC_SCRIPT__',SCRIPT)]:
        html=html.replace(key,value)
    return html.replace('__CC_USER_NAME__',escape(str(user['name']),quote=True))

